# -*- coding: utf-8 -*-
TIER2_HEAD = r'<b>【 แบบที่ 2 ▸ พื้นฐาน · กระชับ · แยกกรณีด้วยสูตรผลบวกอาร์กแทนเจนต์ (case split on the arctangent addition rule) 】</b>'
TIER2 = [
    r'🎯 <b>เหมาะกับ</b> เด็กปานกลางถึงเก่ง · รู้ว่าสูตรผลบวกอาร์กแทนเจนต์มีเงื่อนไข $uv < 1$ กำกับอยู่ และตรวจเครื่องหมายของ $uv - 1$ ก่อนหยิบสูตรมาใช้เสมอ',
    r'<b>ขั้นที่ 1:</b> อ่านโดเมนก่อนลงมือ ตัวส่วน $1 + x$ ห้ามเป็นศูนย์',
    r'⇒ โดเมนคือ $(-\infty , -1) \cup (-1 , \infty)$ ⇒ ขาดเป็นสองท่อนที่เดินข้ามหากันไม่ได้ ⇒ ต้องหาค่า $f$ แยกทีละท่อน',
    r'<b>ขั้นที่ 2:</b> ให้ $u = x$ และ $v = \dfrac{1-x}{1+x}$ แล้วตรวจเครื่องหมายของ $uv - 1$',
    r'⇒ $uv - 1 = \dfrac{x(1-x)}{1+x} - 1 = \dfrac{x - x^{2} - 1 - x}{1+x} = -\dfrac{1 + x^{2}}{1 + x}$ ⇒ ตัวเศษ $1 + x^{2}$ เป็นบวกเสมอ ⇒ เครื่องหมายของ $uv - 1$ ตรงข้ามกับของ $1 + x$ ⇒ ถ้า $x > -1$ ได้ $uv < 1$ · ถ้า $x < -1$ ได้ $uv > 1$',
    r'<b>ขั้นที่ 3:</b> ท่อน $x > -1$ มี $uv < 1$ จึงใช้สูตร $\arctan u + \arctan v = \arctan\dfrac{u+v}{1-uv}$ ได้ตรง ๆ',
    r'⇒ $u + v = x + \dfrac{1-x}{1+x} = \dfrac{1 + x^{2}}{1+x}$ และ $1 - uv = \dfrac{1 + x^{2}}{1+x}$ ⇒ อัตราส่วนเท่ากับ $1$ ⇒ $f(x) = \arctan 1 = \dfrac{\pi}{4}$ ทุกจุดในท่อนนี้',
    r'<b>ขั้นที่ 4:</b> ท่อน $x < -1$ มี $uv > 1$ และ $u = x < 0$ ⇒ สูตรฉบับเต็มบังคับให้ลบ $\pi$ ออกจากค่าอาร์กแทน',
    r'⇒ $f(x) = \arctan\dfrac{u+v}{1-uv} - \pi = \dfrac{\pi}{4} - \pi = -\dfrac{3\pi}{4}$ ทุกจุดในท่อนนี้ ⇒ ลองจุดจริง $x = -2$ ได้ $\arctan(-2) + \arctan(-3) \approx -2.356$ ซึ่งเท่ากับ $-\dfrac{3\pi}{4}$ พอดี',
    r'<b>ขั้นที่ 5:</b> รวมค่าของสองท่อนเข้าด้วยกัน โดยแต่ละท่อนมีจุดยืนยันจริงคือ $x = 0$ ให้ $\dfrac{\pi}{4}$ และ $x = -2$ ให้ $-\dfrac{3\pi}{4}$',
    r'⇒ เรนจ์ของ $f$ คือ $\left\{-\dfrac{3\pi}{4} , \dfrac{\pi}{4}\right\}$ ⇒ เป็นเซตสองสมาชิก ไม่ใช่ช่วง เพราะ $f$ คงที่เป็นท่อน ๆ จึงไม่เคยรับค่าระหว่างกลางเลย',
]
TIER3_HEAD = r'<b>【 แบบที่ 3 ▸ ⚡ ประยุกต์ · แทนด้วยแทนเจนต์ (tangent substitution) 】</b>'
TIER3 = [
    r'⚡ <b>เหมาะกับ</b> เด็กที่พื้นฐานคณิตดี มองออกว่า $\dfrac{1-x}{1+x}$ คือหน้าตาของสูตรผลต่างแทนเจนต์ที่มุม $\dfrac{\pi}{4}$ จึงเปลี่ยนตัวแปรทีเดียวจบ',
    r'<b>ขั้นที่ 1:</b> แทน $x = \tan\alpha$ เมื่อ $\alpha \in \left(-\dfrac{\pi}{2} , \dfrac{\pi}{2}\right)$ ซึ่งกวาด $x$ ครบทุกจำนวนจริงโดยไม่ซ้ำ',
    r'⇒ $\dfrac{1 - x}{1 + x} = \dfrac{1 - \tan\alpha}{1 + \tan\alpha} = \tan\left(\dfrac{\pi}{4} - \alpha\right)$ เพราะ $\tan\dfrac{\pi}{4} = 1$',
    r'<b>ขั้นที่ 2:</b> ใส่กลับเข้านิพจน์ จำไว้ว่า $\arctan\tan\theta$ คืนค่า $\theta$ บวกจำนวนเท่าของ $\pi$ ไม่ใช่ $\theta$ ตรง ๆ',
    r'⇒ $f = \alpha + \arctan\tan\left(\dfrac{\pi}{4} - \alpha\right) = \alpha + \left(\dfrac{\pi}{4} - \alpha\right) + n\pi = \dfrac{\pi}{4} + n\pi$ เมื่อ $n$ เป็นจำนวนเต็ม ⇒ ตัว $\alpha$ ตัดหายไปหมด',
    r'<b>ขั้นที่ 3:</b> คัด $n$ ด้วยกรอบของ $f$ เอง ⇒ $f$ เป็นผลบวกของอาร์กแทนเจนต์สองตัว ซึ่งแต่ละตัวอยู่ใน $\left(-\dfrac{\pi}{2} , \dfrac{\pi}{2}\right)$',
    r'⇒ $f$ ต้องอยู่ในช่วง $(-\pi , \pi)$ ⇒ เหลือเพียง $n = 0$ ให้ $\dfrac{\pi}{4}$ กับ $n = -1$ ให้ $-\dfrac{3\pi}{4}$',
    r'<b>ขั้นที่ 4:</b> ยืนยันว่าเกิดจริงทั้งสองค่า ⇒ แทน $x = 0$ ได้ $\dfrac{\pi}{4}$ และแทน $x = -2$ ได้ $-\dfrac{3\pi}{4}$ ⇒ เรนจ์คือ $\left\{-\dfrac{3\pi}{4} , \dfrac{\pi}{4}\right\}$',
    r'<b>ข้อต่าง:</b> ไม่ต้องคำนวณ $uv - 1$ และไม่ต้องจำสูตรผลบวกอาร์กแทนเจนต์ฉบับแยกกรณีอย่างแบบที่ 1–2 ⇒ พจน์ $n\pi$ โผล่มาเองจากคาบของ $\tan$ แล้วช่วง $(-\pi , \pi)$ คัด $n$ ให้แทนการตรวจเครื่องหมายทีละท่อน',
]
